class MyThread extends Thread {
    public void run() {
        System.out.println("Thread is running");
    }
}

class MyRunnable implements Runnable {
    public void run() {
        System.out.println("Runnable is running");
    }
}

class BatchUploader extends Thread {
    private String batchName;

    public BatchUploader(String batchName) {
        this.batchName = batchName;
    }

    public void run() {
        System.out.println("Uploading marks for " + batchName + "...");
        try {
            Thread.sleep(2000); // Simulating upload time
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        System.out.println("Upload completed for " + batchName);
    }
}

public class MarkUploadSystem {
    public static void main(String[] args) throws InterruptedException {
        System.out.println("Starting mark uploads...");

        BatchUploader b1 = new BatchUploader("Batch A");
        BatchUploader b2 = new BatchUploader("Batch B");
        BatchUploader b3 = new BatchUploader("Batch C");

        b1.start();
        b2.start();
        b3.start();

        b1.join();
        b2.join();
        b3.join();

        System.out.println("All uploads complete. Generating reports...");
    }
}

